// Gradient Descent Compared — Algorithms, route: jsx
// Source: original:essay/optimizer-race
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';

// ---- inlined from optimizer ----
/**
 * Three optimizers descending one closed-form two-basin loss surface:
 *
 *   f(x, y) = (x^2 - 1)^2 + 2.2 y^2 + 0.3 x
 *
 * Basins at x = ±1; the tilt makes the left one the global minimum (~ -0.30) while the
 * start point drains toward the shallower right basin (~ +0.29). Momentum and Adam settle
 * there; SGD's gradient noise eventually kicks it back over the saddle and it finds the
 * global minimum — noise as accidental exploration is the story, verified against the
 * rendered trace (SGD ends near -0.27). SGD carries seeded gradient noise (that is the
 * "stochastic"), momentum carries velocity, Adam normalizes per-coordinate.
 */

const SEED = 20260823;

/** mulberry32: a fixed seed keeps every descent identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const loss = (x: number, y: number): number => (x * x - 1) ** 2 + 2.2 * y * y + 0.3 * x;
const grad = (x: number, y: number): [number, number] => [4 * x * (x * x - 1) + 0.3, 4.4 * y];

/** The viewport in loss-surface coordinates; both basins are inside it. */
const DOMAIN = { x0: -1.75, x1: 1.75, y0: -1.05, y1: 1.45 };

const START: [number, number] = [0.12, 1.25];
const OPT_STEPS = 110;

interface OptimizerTrace {
  name: string;
  /** Position after each step, START first; OPT_STEPS + 1 entries. */
  points: [number, number][];
  /** Loss at each of those positions. */
  losses: number[];
}

function descend(name: string, step: (x: number, y: number, i: number) => [number, number]): OptimizerTrace {
  let [x, y] = START;
  const points: [number, number][] = [[x, y]];
  for (let i = 0; i < OPT_STEPS; ++i) {
    [x, y] = step(x, y, i);
    points.push([x, y]);
  }
  return { name, points, losses: points.map(([px, py]) => loss(px, py)) };
}

const optimizerTraces: OptimizerTrace[] = (() => {
  const random = seededRandom(SEED);
  const gauss = () => {
    const u = Math.max(random(), 1e-9);
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * random());
  };

  const sgd = descend('SGD', (x, y) => {
    const [gx, gy] = grad(x, y);
    const lr = 0.045;
    const noise = 1.4;
    return [x - lr * (gx + noise * gauss()), y - lr * (gy + noise * gauss())];
  });

  const velocity: [number, number] = [0, 0];
  const momentum = descend('Momentum', (x, y) => {
    const [gx, gy] = grad(x, y);
    const beta = 0.93;
    const lr = 0.016;
    velocity[0] = beta * velocity[0] - lr * gx;
    velocity[1] = beta * velocity[1] - lr * gy;
    return [x + velocity[0], y + velocity[1]];
  });

  const m: [number, number] = [0, 0];
  const v: [number, number] = [0, 0];
  const adam = descend('Adam', (x, y, i) => {
    const g = grad(x, y);
    const b1 = 0.9;
    const b2 = 0.999;
    const lr = 0.055;
    const out: [number, number] = [x, y];
    for (const k of [0, 1] as const) {
      m[k] = b1 * m[k] + (1 - b1) * g[k];
      v[k] = b2 * v[k] + (1 - b2) * g[k] * g[k];
      const mHat = m[k] / (1 - b1 ** (i + 1));
      const vHat = v[k] / (1 - b2 ** (i + 1));
      out[k] -= (lr * mHat) / (Math.sqrt(vHat) + 1e-8);
    }
    return out;
  });

  return [sgd, momentum, adam];
})();

/** Loss sampled on a GRID_COLS x GRID_ROWS lattice over DOMAIN, for d3.contours. */
const GRID_COLS = 140;
const GRID_ROWS = 100;

const lossGrid: number[] = (() => {
  const values: number[] = [];
  for (let row = 0; row < GRID_ROWS; ++row) {
    for (let col = 0; col < GRID_COLS; ++col) {
      const x = DOMAIN.x0 + ((col + 0.5) / GRID_COLS) * (DOMAIN.x1 - DOMAIN.x0);
      const y = DOMAIN.y1 - ((row + 0.5) / GRID_ROWS) * (DOMAIN.y1 - DOMAIN.y0);
      values.push(loss(x, y));
    }
  }
  return values;
})();

/** Denser near the basin floors, where the argument happens. */
const lossThresholds: number[] = (() => {
  const min = Math.min(...lossGrid);
  const max = Math.max(...lossGrid);
  return Array.from({ length: 12 }, (_, i) => min + (max - min) * ((i + 1) / 13) ** 1.6);
})();

const TICK_MS = 70;
const HOLD_TICKS = 40;
const COLORS = ['#e0538a', '#e8a63a', '#3fa66a']; // SGD, Momentum, Adam
const AGE_BANDS = [
  { maxAge: 12, opacity: 0.95 },
  { maxAge: 32, opacity: 0.5 },
  { maxAge: Infinity, opacity: 0.2 }
];
/** Where d/dx of the surface vanishes in the deeper left basin — nobody goes there. */
const GLOBAL_MIN: [number, number] = [-1.037, 0];

export default function OptimizerRace({ width }: { width: number }) {
  const safeWidth = Math.max(1, width);
  const scale = safeWidth / GRID_COLS;
  const surfaceHeight = Math.round(scale * GRID_ROWS);
  const height = surfaceHeight + 20;

  // The SSR frame is all three descents complete; the effect rewinds and replays the race.
  const [step, setStep] = useState(OPT_STEPS);

  useEffect(() => {
    const end = OPT_STEPS + HOLD_TICKS;
    setStep(0);
    const id = window.setInterval(() => setStep((s) => (s >= end ? 0 : s + 1)), TICK_MS);
    return () => window.clearInterval(id);
  }, []);

  const shown = Math.min(step, OPT_STEPS);

  /** Loss contours as stacked translucent fills: the more bands cover you, the higher f. */
  const bands = useMemo(() => {
    const contours = d3.contours().size([GRID_COLS, GRID_ROWS]).thresholds(lossThresholds)(lossGrid);
    const path = d3.geoPath();
    return contours.map((contour) => path(contour) ?? '');
  }, []);

  const toPixel = useMemo(() => {
    const spanX = DOMAIN.x1 - DOMAIN.x0;
    const spanY = DOMAIN.y1 - DOMAIN.y0;
    return ([x, y]: [number, number]): [number, number] => [
      ((x - DOMAIN.x0) / spanX) * safeWidth,
      ((DOMAIN.y1 - y) / spanY) * surfaceHeight
    ];
  }, [safeWidth, surfaceHeight]);

  /** Trails in three age bands, newest brightest, so each path fades behind its head. */
  const trails = useMemo(
    () =>
      optimizerTraces.map((trace) => {
        const segments = AGE_BANDS.map(() => [] as string[]);
        for (let j = 0; j < shown; ++j) {
          const age = shown - j;
          const band = AGE_BANDS.findIndex(({ maxAge }) => age <= maxAge);
          const [x0, y0] = toPixel(trace.points[j]);
          const [x1, y1] = toPixel(trace.points[j + 1]);
          segments[band].push(`M${x0.toFixed(1)},${y0.toFixed(1)}L${x1.toFixed(1)},${y1.toFixed(1)}`);
        }
        return {
          name: trace.name,
          loss: trace.losses[shown],
          head: toPixel(trace.points[shown]),
          bands: segments.map((s, b) => ({ opacity: AGE_BANDS[b].opacity, d: s.join('') }))
        };
      }),
    [shown, toPixel]
  );

  if (width === 0) return null;

  const [minX, minY] = toPixel(GLOBAL_MIN);
  const cross = Math.max(3, safeWidth * 0.006);

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="SGD, momentum and Adam descending the same two-basin loss surface from one start: momentum overshoots the valley floor and swings back, Adam hugs the slope, and both settle in the shallower basin — while SGD's gradient noise zigzags it over the saddle until it stumbles into the global minimum the others never visit"
    >
      <g transform={`scale(${scale})`}>
        {bands.map((d, i) => (
          <path key={i} d={d} fill="var(--muted)" opacity={0.07} />
        ))}
      </g>
      <path
        d={`M${(minX - cross).toFixed(1)},${(minY - cross).toFixed(1)}L${(minX + cross).toFixed(1)},${(minY + cross).toFixed(1)}M${(minX - cross).toFixed(1)},${(minY + cross).toFixed(1)}L${(minX + cross).toFixed(1)},${(minY - cross).toFixed(1)}`}
        stroke="var(--muted)"
        strokeWidth={1.4}
        fill="none"
      />
      <text x={minX} y={minY + cross + 12} textAnchor="middle" fill="var(--muted)" fontSize={10}>
        global minimum
      </text>
      {trails.map((trail, t) => (
        <g key={trail.name}>
          {trail.bands.map(({ opacity, d }, b) => (
            <path
              key={b}
              d={d}
              fill="none"
              stroke={COLORS[t]}
              strokeWidth={1.6}
              strokeLinecap="round"
              opacity={opacity}
            />
          ))}
          <circle cx={trail.head[0]} cy={trail.head[1]} r={Math.max(2.5, safeWidth * 0.004)} fill={COLORS[t]} />
        </g>
      ))}
      {trails.map((trail, t) => (
        <text
          key={trail.name}
          x={4 + t * Math.max(90, safeWidth * 0.17)}
          y={height - 6}
          fill={COLORS[t]}
          fontSize={11}
          fontWeight={600}
        >
          {`${trail.name} ${trail.loss.toFixed(3)}`}
        </text>
      ))}
      <text x={width - 4} y={height - 6} textAnchor="end" fill="var(--muted)" fontSize={11}>
        {`step ${shown} / ${OPT_STEPS}`}
      </text>
    </svg>
  );
}
